import csv, collections as C, statistics as S
from datetime import datetime
from itertools import product
def read(f):return list(csv.DictReader(open('data/'+f+'.csv')))
def dt(s):return datetime.fromisoformat(s.replace('Z','+00:00'))
i,a,staff=map(read,['incidents','activity','staffing'])
assert len({r['incident_id'] for r in i})==len(i)
ad={r['incident_id']:r for r in a}
assert len(ad)==len(a) and ad.keys()<={r['incident_id'] for r in i}
cut=dt('2026-06-08T00:00:00Z')
def group(rows,*keys):
 d=C.defaultdict(list)
 for r in rows:d[tuple(r[k] for k in keys)].append(r)
 return d
for r in i:
 r['day']=r['opened_at'][:10]
 assert (dt(r['opened_at'])>=cut)==(r['workflow']=='assist')
 x=ad.get(r['incident_id'])
 r['t']=None
 if x:
  r.update(x)
  if x['closed_at']:r['t']=(dt(x['closed_at'])-dt(r['opened_at'])).total_seconds()/60
  for k in ['responder_minutes','handoffs','reopened_within_72h']:r[k]=int(r[k]) if r[k] else None
 r['late']=r['t'] is None or r['t']>10080
 r['cap']=min(r['t'],10080) if r['t'] is not None else 10080
 r['missing']=x is None
 assert r['t'] is None or r['t']>=0
def vals(rs,k):return [r[k] for r in rs if r.get(k) is not None]
def f(x):return round(x,2)
def stats(rs):
 return [len(rs),sum(r['missing'] for r in rs),sum(r['late'] for r in rs),*[f(fn(vals(rs,k))) if vals(rs,k) else None for k,fn in [('t',S.median),('t',S.mean),('cap',S.mean),('responder_minutes',S.mean),('responder_minutes',sum),('handoffs',S.mean),('reopened_within_72h',S.mean)]]]
for keys in [('workflow',),('workflow','severity'),('workflow','service_group'),('workflow','service_group','severity'),('workflow','intake_channel'),('day',)]:
 print(keys)
 for k,rs in sorted(group(i,*keys).items()):print(k,stats(rs))
print('missing and late')
for r in i:
 if r['late'] or r['missing']:print(r)
print('activity crosses',sum(r['workflow']=='manual' and r['t'] is not None and dt(r['closed_at'])>=cut for r in i))
for k,rs in group(staff,'date').items():assert sum(int(r['incidents_opened']) for r in rs)==len(group(i,'day')[k])
for w,rs in [('manual',staff[:14]),('assist',staff[14:])]:print(w,{k:sum(int(r[k]) for r in rs) for k in ['scheduled_responder_hours','interruption_minutes','incidents_opened']})
print('standardized')
for keys in [('severity',),('severity','service_group'),('severity','service_group','intake_channel')]:
 g=group(i,*keys)
 print(keys,sorted((k,len(vals([r for r in rs if r['workflow']=='manual'],'t')),len(vals([r for r in rs if r['workflow']=='assist'],'t'))) for k,rs in g.items()))
 for target in ['manual','assist','pooled']:
  for outcome in ['t','cap','responder_minutes','handoffs','reopened_within_72h','late']:
   out=[0,0]; n=0
   for rs in g.values():
    m,b=[vals([r for r in rs if r['workflow']==w],outcome) for w in ['manual','assist']]
    if not m or not b:continue
    weight=sum(target in ('pooled',r['workflow']) for r in rs)
    n+=weight
    for j,l in enumerate([m,b]):out[j]+=weight*S.mean(l)
   print(target,outcome,n,[f(v/n) for v in out],f((out[1]-out[0])/n), f((out[1]-out[0])/n*210/60))
