from math import ceil
def quant(rs,k,p):
 v=sorted(vals(rs,k));return v[ceil(p*len(v))-1]
for k,rs in group(i,'workflow').items():
 print(k,'cap med/p90/p95',[quant(rs,'cap',p) for p in [.5,.9,.95]],'close in 24h',sum(r['t'] is not None and r['t']<=1440 for r in rs),'reopens',sum(vals(rs,'reopened_within_72h')),'late 72h followup',sum(r['t'] is not None and (dt('2026-06-22T23:59:00Z')-dt(r['closed_at'])).total_seconds()<72*3600 for r in rs))
g=group(i,'severity','service_group')
for k,rs in sorted(g.items()):
 m,b=[[r for r in rs if r['workflow']==w] for w in ['manual','assist']]
 print(k,'contribution assist mix',len(b)*(S.mean(vals(b,'responder_minutes'))-S.mean(vals(m,'responder_minutes')))/60)
print('base hours assist mix',sum(sum(r['workflow']=='assist' for r in rs)*S.mean(vals([r for r in rs if r['workflow']=='manual'],'responder_minutes')) for rs in g.values())/60)
print('staff group')
for k,rs in group(staff,'service_group').items():
 for w in [rs[:7],rs[7:]]: print(k, [sum(int(r[field]) for r in w) for field in ('scheduled_responder_hours','interruption_minutes')])
print('weighted medians t/cap')
for metric in ['t','cap']:
 for w in ['manual','assist']:
  h=[]
  for rs in g.values():
   value=vals([r for r in rs if r['workflow']==w],metric)
   h.extend((v,sum(r['workflow']=='assist' for r in rs)/len(value)) for v in value)
  running=0
  for v,weight in sorted(h):
   running+=weight
   if running>=105: print(metric,w,v);break
